INSERT INTO public.performance_tasks ("id", "goal_id", "employee_id", "task_type", "general_task_id", "title", "description", "target_date", "status", "completed_at", "employee_learnings", "employee_feedback", "supervisor_feedback", "supervisor_accomplishment", "created_at", "updated_at")
VALUES
('task-gen-01', 'goal-b0e6f19a', 'emp-101', 'general', 'gtask-1', 'Hospitality 5-Star Standard Operating Procedure (SOP) Refresher', 'Review hotel front-of-house service protocols and luxury guest greeting guidelines.', '2026-09-15', 'completed', '2026-08-22T14:30:00+08:00', 'Refreshed knowledge on luxury greeting cadence, eye contact within 10 feet, and bespoke menu storytelling.', 'Suggest updating the digital wine menu on tablets for faster tableside lookup.', 'Excellent dedication. Maria applied the greeting protocol effectively during VIP check-in.', 'Awarded 5-Star Commendation from Front Office Manager.', '2026-08-20T10:00:00+00:00', '2026-08-22T14:30:00+00:00'),
('task-gen-02', 'goal-b0e6f19a', 'emp-101', 'general', 'gtask-2', 'Daily Shift Quality & Sanitation Checklist Compliance', 'Complete daily shift handover inspection and verify zero hygiene or protocol discrepancies.', '2026-09-20', 'completed', '2026-08-24T16:45:00+08:00', 'Mastered the 14-point sanitation checklist across POS stations and lounge tables.', 'Lounge POS terminal stylus needs replacement.', 'All checklists submitted with zero remarks. Consistent hygiene compliance maintained.', 'Shift audit passed with 100% QA score.', '2026-08-20T10:00:00+00:00', '2026-08-24T16:45:00+00:00'),
('task-spec-01', 'goal-b0e6f19a', 'emp-101', 'specific', NULL, 'Sommelier Reserve Wine Pairing Workshop & Shadowing Session', 'Shadow Head Sommelier Pierre for 2 evening dinner services to practice French Bordeaux & Italian vintage recommendations.', '2026-09-18', 'completed', '2026-08-25T21:15:00+08:00', 'Gained confidence explaining vintage profiles, acidity balance with Wagyu steak, and tasting notes to discerning diners.', 'Would love a quick pocket cheat-sheet for seasonal cellar reserves.', 'Maria successfully recommended 3 premium reserve bottles during dinner rush, lifting average beverage check by +22%.', 'Recorded +$480 beverage upsell on Aug 25 evening service.', '2026-08-20T10:00:00+00:00', '2026-08-25T21:15:00+00:00'),
('task-spec-02', 'goal-b0e6f19a', 'emp-101', 'specific', NULL, 'Micros POS Fast-Split Billing & VIP Account Routing Certification', 'Complete hands-on simulation test on splitting multi-guest checks and charging club floor lounge tabs within 45 seconds.', '2026-09-25', 'pending', NULL, NULL, NULL, NULL, NULL, '2026-08-20T10:00:00+00:00', '2026-08-20T10:00:00+00:00'),
('task-gen-03', 'goal-088645a3', 'emp-101', 'general', 'gtask-1', 'Hospitality 5-Star Standard Operating Procedure (SOP) Refresher', 'Review housekeeping 5-star room preparation SOPs and guest room amenities layout.', '2026-09-15', 'completed', '2026-08-23T11:00:00+08:00', 'Memorized the 20-point presidential suite layout standard including pillow arrangement and linen alignment.', 'New microfiber cloths improved mirror cleaning speed.', 'High attention to detail displayed during room inspection.', 'Suite passed floor manager inspection with 0 defects.', '2026-08-20T10:00:00+00:00', '2026-08-23T11:00:00+00:00'),
('task-spec-03', 'goal-088645a3', 'emp-101', 'specific', NULL, 'Executive Suite Express Turnaround Drill (Target < 20 mins)', 'Conduct timed room turnarounds with executive housekeeper to optimize movement pattern and linen staging.', '2026-09-22', 'pending', NULL, NULL, NULL, NULL, NULL, '2026-08-20T10:00:00+00:00', '2026-08-20T10:00:00+00:00'),
