INSERT INTO public.training_programs ("id", "title", "category", "categoryType", "dept", "targetCompetency", "competencyKey", "duration", "format", "trainerType", "passingScore", "xpAward", "icon", "badgeColor", "description", "modules", "quizQuestions")
VALUES
('prog-1', 'Hospitality Crisis Diplomacy & Guest De-escalation', 'Skill Gap: Service Excellence', 'skill_gap', 'Front Office', 'Frontline Conflict De-escalation', 'de_escalation', '3.5 Hours (1 Day Workshop)', 'In-Person Workshop & Roleplay', 'Internal Master Trainer', 80, 150, 'fa-handshake-angle', 'terracotta', 'Comprehensive training covering the LAST de-escalation framework (Listen, Apologize, Solve, Thank), emotional intelligence under pressure, and diplomatic service recovery vouchers.', '["1. Anatomy of Guest Frustration & Empathy Triggers","2. The LAST Protocol in Real Hospitality Scenarios","3. Body Language, Vocal Cadence & Boundary Setting","4. Live Simulations & Practical Scenario Assessment"]', '[{"q":"What does the \"A\" in the LAST hospitality recovery framework represent?","options":["Argue the policy diplomatically","Apologize sincerely for the guest''s distress without assigning blame","Ask the manager to intervene immediately","Assess the financial liability"],"correct":1},{"q":"When an agitated guest raises their voice in the lobby, the recommended verbal pace is:","options":["Match their volume and pace so you are heard","Lower your tone, speak 15% slower, and maintain calm open body posture","Remain completely silent until they finish shouting","Immediately step backwards behind the security desk"],"correct":1},{"q":"What is the maximum instant amenity voucher a Front Desk Host may authorize without GM signoff?","options":["\u20b1500 Dining Credit","\u20b12,500 F&B or Spa Voucher + Room Category Upgrade","Free Weekend Stay","\u20b110,000 Cash Refund"],"correct":1},{"q":"During de-escalation, which phrase should ALWAYS be avoided?","options":["\"I completely understand your frustration and I will personally solve this.\"","\"That''s not our hotel policy and there is nothing I can do.\"","\"Let me see what alternatives I can immediately arrange for you.\"","\"Thank you for bringing this to our attention right away.\""],"correct":1}]'),
('prog-2', 'HACCP Level 3 Food Safety & Cold-Chain Mastery', 'Mandatory Compliance', 'compliance', 'Culinary', 'HACCP Safety & Sanitation', 'haccp_safety', '4.0 Hours', 'Hygiene Lab & Inspection Walk', 'Certified External Auditor', 85, 150, 'fa-utensils', 'sage', 'Certified standard training on critical control points (CCP), digital cold-chain data logging, allergen cross-contact segregation, and sanitization protocols.', '["1. Critical Control Points & Walk-in Chiller Thresholds","2. Color-coded Board Segregation & Cross-Contamination","3. Blast Chilling, Core Probe Calibration & FIFO Logs","4. Health Authority Audit Compliance Walkthrough"]', '[{"q":"What is the mandatory temperature range for hotel walk-in meat chillers?","options":["0\u00b0C to 1\u00b0C","2\u00b0C to 4\u00b0C","5\u00b0C to 8\u00b0C","-5\u00b0C to 0\u00b0C"],"correct":1},{"q":"Which cutting board color is strictly reserved for raw poultry?","options":["Blue","Yellow","Red","Green"],"correct":1}]'),
('prog-3', 'Sommelier Fine Wine Pairing & Vintage Storytelling', 'Skill Gap: Revenue Optimization', 'skill_gap', 'F&B Service', 'Revenue & Wine Upsell', 'revenue_upsell', '3.0 Hours', 'Tasting Workshop & Tableside Service', 'Master Sommelier', 80, 150, 'fa-wine-glass-empty', 'gold', 'Tasting workshop covering Old World vs New World terroirs, tableside decanting ritual, tasting pour etiquette, and food pairing storytelling.', '["1. Bordeaux, Burgundy & Tuscan Vintage Profiles","2. Tableside Decanting Etiquette & Glassware Selection","3. Acidity & Tannin Balancing with Tasting Menus","4. Premium Cellar Upselling Dialogue"]', '[{"q":"What is the correct tableside tasting pour volume when presenting wine to the host?","options":["10ml","30ml (1 oz)","75ml","150ml"],"correct":1},{"q":"Where should the wine bottle label face during pouring?","options":["Towards the floor","Facing directly towards the guest being served","Facing the sommelier","Covered with a napkin"],"correct":1}]')
